<?php
declare(strict_types=1);
require_once __DIR__ . '/../../app/Auth.php';
exigirAdmin();
function ejecutarIpconfig(): string { return shell_exec('ipconfig /all 2>&1') ?? ''; }
function detectarInterfaces(string $salida): array { $interfaces=[];$bloques=preg_split('/(?=^\s*(?:Adaptador|Adapter)\s+)/mi',$salida);foreach($bloques as $bloque){if(trim($bloque)==='')continue;$nombre='';if(preg_match('/^\s*(?:Adaptador|Adapter)\s+(.*?):\s*$/mi',$bloque,$m))$nombre=trim($m[1]);$ip=null;if(preg_match('/IPv4[^:]*:\s*([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)/i',$bloque,$m))$ip=$m[1];$interfaces[]=['nombre'=>$nombre,'ip'=>$ip,'wifi'=>(bool)preg_match('/wi[\s-]?fi|wifi|inal[aá]mbrica|wireless/i',$nombre.' '.$bloque),'activo'=>$ip!==null];}return $interfaces; }
$wifi=null;foreach(detectarInterfaces(ejecutarIpconfig()) as $interfaz){if($interfaz['wifi']&&$interfaz['activo']&&filter_var($interfaz['ip'],FILTER_VALIDATE_IP,FILTER_FLAG_IPV4)){$wifi=$interfaz;break;}}
$urlMovil=$wifi?'https://'.$wifi['ip'].'/movil':'';
?>
